"""The adder tree through DC, at one top. Generated by reduce_asic.py."""

import os

from mflowgen.components import Graph, Node


def construct():
  graph = Graph()
  adk_name = 'freepdk-45nm'
  design_path = os.environ['REDUCE_RTL']
  top = os.environ['REDUCE_TOP']
  manifest = os.environ['REDUCE_MANIFEST']

  parameters = {
    'construct_path': __file__,
    'design_name': top,
    'top_module': top,
    'adk': adk_name,
    'adk_view': 'view-standard',
    'clock_period': 3.33,
    'clock_port': 'ap_clk',
    'topographical': True,
    'flatten_effort': 3,
    'design_path': os.path.join(design_path, 'rtl'),
    'manifest': os.path.join(design_path, manifest),
    'sv2v_include_dirs': '.',
    'normalize_rtl': False,
    'sram_mode': 'none',
  }

  # The vendored flow is allo/backend/asic/{nodes,adks}. Search upward for it
  # rather than counting directories up from here -- the same rule
  # construct-commercial.py follows, and for the same reason: a count encodes
  # tree shape, and this tree is being reorganised. ALLO_ASIC_FLOW is for when
  # this generated file is run from a copy outside the checkout, which is what
  # the /scratch build trees on the synthesis host are.
  asic_dir = os.environ.get('ALLO_ASIC_FLOW')
  if not asic_dir:
    d = os.path.dirname(os.path.abspath(__file__))
    while True:
      candidate = os.path.join(d, 'allo', 'backend', 'asic')
      if os.path.isdir(os.path.join(candidate, 'nodes')):
        asic_dir = candidate
        break
      parent = os.path.dirname(d)
      if parent == d:
        raise SystemExit(
          'no allo/backend/asic/nodes in any parent of '
          f'{os.path.dirname(os.path.abspath(__file__))}. Set ALLO_ASIC_FLOW to '
          'a checkout of the flow, or run '
          'allo/backend/asic/tools/preflight.py to see what is missing.')
      d = parent
  nodes_dir = os.path.join(asic_dir, 'nodes')
  if not os.path.isdir(nodes_dir):
    raise SystemExit(f'ALLO_ASIC_FLOW={asic_dir} has no nodes/ directory.')
  graph.sys_path.append(os.path.join(asic_dir, 'adks'))
  graph.set_adk(adk_name)
  adk = graph.get_adk_node()

  names = ['sv2v-design-collector', 'sram-collateral',
           'asic-flow-utilities', 'synopsys-dc-synthesis']
  nodes = {n: Node(os.path.join(nodes_dir, n)) for n in names}
  for node in nodes.values():
    graph.add_node(node)
  synth = nodes['synopsys-dc-synthesis']
  graph.connect_by_name(adk, synth)
  graph.connect_by_name(nodes['sram-collateral'], synth)
  graph.connect_by_name(nodes['sv2v-design-collector'], synth)
  graph.connect_by_name(nodes['asic-flow-utilities'], synth)
  graph.update_params(parameters)
  return graph
